  if(!panel)return;let host=panel.querySelector('#hair-categories');if(!host){host=document.createElement('div');host.id='hair-categories';host.innerHTML='<nav class="hair-category-tabs" aria-label="发型分类">'+[['front','前发'],['back','后发'],['single','单品']].map(([category,label])=>`<button data-hair-filter="${category}">${label}</button>`).join('')+'<button class="hair-category-clear" data-clear-hair-category>取下本分类</button></nav>'+['front','back','single'].map(category=>`<details class="hair-section" data-hair-category-section="${category}" open><summary>${{front:'前发',back:'后发',single:'单品'}[category]} <span data-category-count></span></summary><div class="hair-grid" data-category-grid></div></details>`).join('');panel.querySelector('.hair-color-section').after(host);host.onclick=e=>{const filter=e.target.closest('[data-hair-filter]');if(filter){hairCategoryFilter=filter.dataset.hairFilter;renderHairCategories();return;}if(e.target.closest('[data-clear-hair-category]')){for(const side of ['front','back']){saved.pieces[side]=selectedPieces(side).filter(id=>hairCategory(side,id)!==hairCategoryFilter);selectPart(side,saved.pieces[side].at(-1)||'none');}save();update();}};host.onchange=e=>{const control=e.target.closest('[data-hair-classify]');if(!control)return;assignHairCategory(control.dataset.side,control.dataset.id,control.value);hairCategoryFilter=control.value;save();update();};}
