 function dyeBox(side,id,f){const extra=sclubChoice(side,id)||singleChoice(side,id)||fantasyChoice(side,id)||inspirationChoice(side,id)||asymmetryChoice(side,id);const generic=genericRearChoice(side,id);if(generic)return genericRearBox(generic,f);if(refinedRear(side,id))return rearGeometry(f);if(extra){const b=sclubBounds[extra[0]][side],rx=f.scale/1.2*(f.sx||1),ry=f.scale/1.2*(f.sy||1);return {x:470+(b[0]-470)*rx+f.x,y:180+(b[1]-180)*ry+f.y,w:(b[2]-b[0])*rx,h:(b[3]-b[1])*ry};}return {x:470-90*f.scale*(f.sx||1)+f.x,y:15+f.y,w:180*f.scale*(f.sx||1),h:278*f.scale*(f.sy||1)};}
 function fantasyControls(){if(panel.querySelector('#fantasy-styles'))return;const box=document.createElement('details');box.id='fantasy-styles';box.className='hair-section';box.open=true;box.innerHTML='<summary>编发与层次 · 16款</summary><div style="display:flex;flex-wrap:wrap;gap:6px;padding:10px 0">'+fantasyStyles.map((v,i)=>'<button data-fantasy-index="'+i+'">'+v[1]+' · '+(v[2]==='front'?'前发':'后发')+'</button>').join('')+'</div>';panel.querySelector('.hair-color-section').after(box);box.onclick=e=>{const b=e.target.closest('[data-fantasy-index]');if(!b)return;const style=fantasyStyles[Number(b.dataset.fantasyIndex)];if(!style)return;const side=style[2],id=fantasyID(style);saved.pieces[side]=[id];selectPart(side,id);editSide=side;saved.enabled=true;save();update();};}
 function inspirationControls(){if(panel.querySelector('#inspiration-styles'))return;const box=document.createElement('details');box.id='inspiration-styles';box.className='hair-section';box.open=true;box.innerHTML='<summary>灵感新款 · 稀疏刘海</summary><div style="display:flex;flex-wrap:wrap;gap:6px;padding:10px 0">'+inspirationStyles.map((v,i)=>`<button data-inspiration-style="${i}">${v[1]}</button>`).join('')+'</div><small>前五款整款试戴；空气刘海试戴配齐肩后发，也可在前发中单独选用。</small>';panel.querySelector('.hair-color-section').after(box);box.onclick=e=>{const b=e.target.closest('[data-inspiration-style]');if(!b)return;const n=Number(b.dataset.inspirationStyle),id=String(inspirationOffset+n),back=n===5?'25':'none';saved.pieces.front=[id];saved.pieces.back=back==='none'?[]:[back];selectPart('front',id);selectPart('back',back);if(back!=='none'){if(!saved.positionDefaults.back[back]){saved.backFit=cleanFit({...defaultFit(),scale:.9});saved.positionDefaults.back[back]={...saved.backFit};}saved.piecePlacement['back:'+back]='behind';}saved.piecePlacement['front:'+id]='front';editSide='front';saved.enabled=true;save();update();};}
 function asymmetryControls(){if(panel.querySelector('#asymmetry-styles'))return;const box=document.createElement('details');box.id='asymmetry-styles';box.className='hair-section';box.open=true;box.innerHTML='<summary>不对称发型 · 10款</summary><div style="display:flex;flex-wrap:wrap;gap:6px;padding:10px 0">'+asymmetryStyles.map((v,i)=>'<button data-asymmetry-style="'+i+'">'+v[1]+'</button>').join('')+'</div><small>整款试戴；可换色、局部染色和分别调整宽高。</small>';panel.querySelector('.hair-color-section').after(box);box.onclick=e=>{const b=e.target.closest('[data-asymmetry-style]');if(!b)return;const n=Number(b.dataset.asymmetryStyle);if(!asymmetryStyles[n])return;const id=String(asymmetryOffset+n).padStart(2,'0');saved.pieces.front=[id];saved.pieces.back=[];selectPart('front',id);selectPart('back','none');saved.piecePlacement['front:'+id]='front';editSide='front';saved.enabled=true;save();update();};}
