  panel=document.createElement('section');panel.id='hair-panel';panel.hidden=true;panel.innerHTML=`<div class="hair-heading"><strong>发型</strong><button id="hair-close">返回衣服</button></div><details class="hair-section hair-color-section" open><summary>发色</summary><div class="hair-color"><label><input type="checkbox" id="hair-enabled"> 试戴发型</label><label>发色 <input type="color" id="hair-color" value="${saved.color}"></label></div></details>${['front','back'].map(s=>`<details class="hair-section hair-part" open><summary>${s==='front'?'前发':'后发'}</summary><label>款式 <select data-hair-part="${s}"><option value="none">无</option>${choices(s).map((n,i)=>`<option value="${String(i+1).padStart(2,'0')}">${n}</option>`).join('')}</select></label><div class="hair-grid"><button data-hair-choice="none" data-side="${s}" aria-label="${s==='front'?'前发':'后发'}：无"><span>无</span></button>${choices(s).map((n,i)=>`<div class="hair-choice"><button data-hair-choice="${String(i+1).padStart(2,'0')}" data-side="${s}" title="${n}" aria-label="${s==='front'?'前发':'后发'}：${n}"><img src="${thumbURL(s,String(i+1).padStart(2,'0'))}" loading="lazy"><span>${n}</span></button><div class="hair-layer-buttons">${[["front","前"],["behind","后"]].map(([pos,label])=>`<button data-piece-layer="${pos}" data-piece-id="${String(i+1).padStart(2,"0")}" data-side="${s}" aria-label="${n}放人物${label}面">${label}</button>`).join('')}</div></div>`).join('')}</div><div class="hair-fit">${[['x','左右',-939,939,1],['y','上下',-1676,1676,1],['scale','大小',.1,5,.01]].map(([p,n,min,max,step])=>`<label>${n}<input type="range" data-side="${s}" data-fit="${p}" min="${min}" max="${max}" step="${step}"></label>`).join('')}</div></details>`).join('')}<button id="hair-save-position" class="outline-button">保存位置</button><button id="hair-reset" class="outline-button">恢复保存位置</button><span id="hair-saved" role="status">已载入保存位置</span>`;
  document.querySelector('.wardrobe').append(panel);panel.querySelector('#hair-close').onclick=close;panel.querySelector('#hair-enabled').onchange=e=>{saved.enabled=e.target.checked;save();};panel.querySelector('#hair-color').oninput=e=>{saved.color=e.target.value;save();};panel.addEventListener('change',e=>{const s=e.target.dataset.hairPart;if(s){editSide=s;if(e.target.value==='none')saved.pieces[s]=[];else if(!selectedPieces(s).includes(e.target.value))saved.pieces[s].push(e.target.value);selectPart(s,e.target.value);save();update();}});panel.addEventListener('click',e=>{const order=e.target.closest('[data-piece-layer]');if(order){const side=order.dataset.side,id=order.dataset.pieceId;editSide=side;if(!selectedPieces(side).includes(id))saved.pieces[side].push(id);selectPart(side,id);saved.piecePlacement[side+':'+id]=order.dataset.pieceLayer;if(hairCategory(side,id)!=='single')saved.pieceCategory[side+':'+id]=order.dataset.pieceLayer==='front'?'front':'back';storeHairCategories();save();update();return;}const b=e.target.closest('[data-hair-choice]');if(b){editSide=b.dataset.side;togglePiece(b.dataset.side,b.dataset.hairChoice);save();update();}});panel.addEventListener('input',e=>{if(e.target.dataset.fit){editSide=e.target.dataset.side;saved[e.target.dataset.side+'Fit'][e.target.dataset.fit]=Number(e.target.value);positionStatus='位置已调整，点击保存位置';save();update();}});panel.querySelector('#hair-reset').onclick=()=>{for(const side of ['front','back'])saved[side+'Fit']=cleanFit(saved.positionDefaults[side][saved[side]]||defaultFit(side,saved[side]));positionStatus='已恢复保存位置';save();update();};panel.querySelector('#hair-save-position').onclick=commitPositions;mountEditor();mountDye();update();document.querySelector('[data-nav="wardrobe"]').addEventListener('click',close);
